from __future__ import annotations

_LEFT_MARGIN  = 60
# _LEFT_MARGIN  = 200 # new label trial


def _header(pw: int, ll: int) -> str:
    return (
        f"^XA\n"
        f"^CI28\n"
        f"^PW{pw}\n"
        f"^LL{ll}\n"
        f"^LH{_LEFT_MARGIN},18\n" #35 for new label trial
    )


def _footer(quantity: int = 1) -> str:
    return f"^PQ{quantity}\n^XZ\n"


def _fd(text: str) -> str:
    return str(text).replace("^", "").replace("~", "")


def _type_code_from_model(model_number: str) -> str:
    base = model_number.split("-")[0].strip()
    return f"UV_{base}"


def build_hv_module_label_domestic(
    *,
    full_module_id: str,   
) -> str:
    b = _header(120, 120)

    b += f"^FO10,10^BQN,2,3^FDQA,{_fd(full_module_id)}^FS\n"

    y = 100
    b += f"^FO0,{y}^A0N,8,8^FD{_fd(full_module_id)}^FS\n"

    b += _footer()
    return b


def build_hv_module_label_export(
    *,
    full_module_id: str,
) -> str:
    b = _header(120, 120)
    b += f"^FO10,10^BQN,2,3^FDQA,{_fd(full_module_id)}^FS\n"
    y = 100
    b += f"^FO0,{y}^A0N,8,8^FD{_fd(full_module_id)}^FS\n"
    b += _footer()
    return b


def build_hv_pack_label_domestic(
    *,
    module_id: str,
    variant: str,
    model_number: str,
    type_of_reess: str,
    rated_capacity: str,
    tac_number: str,
    mfg_date: str,
) -> str:
    b = _header(1200, 600)

    b += f"^FO20,40^BQN,2,6^FDQA,{_fd(module_id)}^FS\n"

    b += f"^FO300,40^A0N,28,30^FDVariant: {_fd(variant)}^FS\n"
    b += f"^FO300,80^A0N,28,30^FDPart Number: {_fd(model_number)}^FS\n"
    b += f"^FO300,120^A0N,28,30^FDType of REESS: {_fd(type_of_reess)}^FS\n"
    b += f"^FO300,160^A0N,28,30^FDRated Capacity: {_fd(rated_capacity)}^FS\n"
    b += f"^FO300,240^A0N,28,30^FDTAC Number: {_fd(tac_number)}^FS\n"
    b += f"^FO300,280^A0N,28,30^FDMfg Date: {_fd(mfg_date)}^FS\n"
    b += f"^FO300,320^A0N,28,30^FDMade in India^FS\n"
    b += f"^FO300,380^A0N,24,26^FD{_fd(module_id)}^FS\n"

    b += _footer()
    return b


def build_bmb_cmb_combined_zpl(*, bmb_serial: str, cmb_serial: str, pack_qr_data: str = "") -> str:
    b = _header(720, 420)
    if pack_qr_data:
        b += f"^FO20,80^A0N,25,23^FDPack ID: {_fd(pack_qr_data)}^FS\n"
    b += "^FO160,20^A0N,30,32^FDBMS DATA^FS\n"
    b += "^FO160,55^GB150,3,3^FS\n"
    b += f"^FO20,100^BQN,2,5^FDQA,B_{(bmb_serial)}, C_{(cmb_serial)}^FS\n"
    b += f"^FO160,140^A0N,25,25^FDBMB ID: {_fd(bmb_serial)}^FS\n"
    b += f"^FO160,180^A0N,25,25^FDCMB ID: {_fd(cmb_serial)}^FS\n"
    b += _footer(2)
    return b


def build_bmb_cmb_zpl(*, kind: str, value: str, pack_qr_data: str = "") -> str:
    b = _header(600, 300)
    b += f"^FO00,120^BQN,2,8^FDQA,{_fd(value)}^FS\n"
    b += f"^FO160,35^A0N,37,39^FD{_fd(kind)} DATA^FS\n"
    b += f"^FO160,70^GB170,3,3^FS\n"
    if pack_qr_data:
        b += f"^FO00,90^A0N,27,28^FDPack ID: {_fd(pack_qr_data[:31])}^FS\n"
        y = 150
    else:
        y = 140
    b += f"^FO185,{y}^A0N,30,32^FD{_fd(kind)} ID: {_fd(value)}^FS\n"
    b += _footer(2)
    return b


def build_bms_id_zpl(*, bms_id: str, pack_qr_data: str = "") -> str:
    b = _header(600, 300)
    b += f"^FO00,120^BQN,2,8^FDQA,{_fd(bms_id)}^FS\n"
    b += f"^FO160,35^A0N,37,39^FDBMS DATA^FS\n"
    b += f"^FO160,70^GB170,3,3^FS\n"
    if pack_qr_data:
        b += f"^FO00,90^A0N,27,28^FDPack ID: {_fd(pack_qr_data[:31])}^FS\n"
        y_bms = 150
    else:
        y_bms = 140
    b += f"^FO185,{y_bms}^A0N,30,32^FDBMS ID: {_fd(bms_id)}^FS\n"
    b += f"^FO185,{y_bms + 70}^A0N,30,32^FDS/W Version: ^FS\n"
    b += _footer(2)
    return b


def build_pack_qr_zpl(
    *,
    pack_qr_data: str,
    model_number: str,
    serial_number: str,
    tac_number: str,
    tac_label: str = "TAC Number",
    mfg_date: str,
) -> str:
    b = _header(720, 360)
    b += f"^FO240,10^BQN,2,4^FDQA,{_fd(pack_qr_data)}^FS\n"
    b += f"^FO90,130^A0N,26,25^FDModel Number: {_fd(model_number)}^FS\n"
    b += f"^FO90,165^A0N,26,25^FDSerial Number: {_fd(serial_number)}^FS\n"
    y = 200
    if tac_number:
        b += f"^FO90,{y}^A0N,26,25^FD{_fd(tac_label)}: {_fd(tac_number)}^FS\n"
        y += 35
    mfg_label = "Mfg Date" if len(mfg_date) > 4 else "Mfg Year"
    b += f"^FO90,{y}^A0N,26,25^FD{mfg_label}: {_fd(mfg_date)}^FS\n"
    b += _footer(2)
    return b


def build_battery_pack_id_zpl_unified(
    *,
    rated_capacity: str,
    max_voltage: str,
    type_of_reess: str,
    serial_number: str,
    tac_number: str,
    emark_res: str,
    srb_code: str,
    made_in: str,
    mfg_year: str,
    qr_data: str,
) -> str:
    
    b = _header(1100, 600)
    
    b += f"^FO215,30^A0N,27,29^FDRated Capacity: {_fd(rated_capacity)}^FS\n"
    b += f"^FO215,70^A0N,27,29^FDMaximum Voltage: {_fd(max_voltage)}^FS\n"
    b += f"^FO215,140^A0N,24,25^FDModel Number: {_fd(type_of_reess)}^FS\n"
    b += f"^FO215,170^A0N,24,25^FDSerial Number: {_fd(serial_number)}^FS\n"
    b += f"^FO215,200^A0N,24,25^FDTAC Number: {_fd(tac_number)}^FS\n"
    b += "^FO215,250^A0N,27,28^FDSecondary Lithium Ion Battery^FS\n"

    b += "^FO215,290^GE58,58,2,B^FS\n"
    b += "^FO227,303^A0N,34,34^FDE^FS\n"
    b += "^FO243,310^A0N,26,26^FD11^FS\n"
    b += f"^FO277,307^A0N,26,32^FD{_fd(emark_res)}^FS\n"

    b += f"^FO215,360^A0N,36,38^FD{_fd(srb_code)}^FS\n"

    b += f"^FO500,335^BQN,2,4^FDQA,{_fd(qr_data)}^FS\n"

    if made_in:
        b += f"^FO215,400^A0N,24,25^FDMade in {_fd(made_in)}^FS\n"
    b += f"^FO215,430^A0N,24,25^FDMfg Year: {_fd(mfg_year)}^FS\n"

    b += _footer(1)
    return b

